     1→// Australian Football Field Specifications
     2→// Field dimensions vary by venue: ~150-185m length, ~120-155m width
     3→// Using standard dimensions for consistency
     4→
     5→export const FIELD_CONFIG = {
     6→  // Standard field dimensions (in meters)
     7→  length: 165, // meters
     8→  width: 135, // meters
     9→  
    10→  // Center square dimensions
    11→  centerSquareSize: 50, // 50m x 50m
    12→  
    13→  // Center circle radius
    14→  centerCircleRadius: 3, // meters
    15→  
    16→  // Goal posts
    17→  goalPostWidth: 6.4, // meters between posts
    18→  goalPostHeight: 6, // meters height
    19→  
    20→  // Scale factor for 3D scene (1 unit = 1 meter)
    21→  scale: 1,
    22→} as const;
    23→
    24→export interface FieldGeometry {
    25→  vertices: Float32Array;
    26→  indices: Uint16Array;
    27→}
    28→
    29→// Generate oval field shape
    30→export function generateFieldGeometry(): FieldGeometry {
    31→  const { length, width } = FIELD_CONFIG;
    32→  const segments = 64; // Number of segments for smooth oval
    33→  
    34→  const vertices: number[] = [];
    35→  const indices: number[] = [];
    36→  
    37→  // Generate oval vertices
    38→  for (let i = 0; i <= segments; i++) {
    39→    const angle = (i / segments) * Math.PI * 2;
    40→    const x = (length / 2) * Math.cos(angle);
    41→    const z = (width / 2) * Math.sin(angle);
    42→    vertices.push(x, 0, z);
    43→  }
    44→  
    45→  // Generate indices for oval outline
    46→  for (let i = 0; i < segments; i++) {
    47→    indices.push(i, i + 1);
    48→  }
    49→  
    50→  return {
    51→    vertices: new Float32Array(vertices),
    52→    indices: new Uint16Array(indices),
    53→  };
    54→}
