     1→import { create } from 'zustand';
     2→import { Player, createTeamPlayers, DEFAULT_TEAM_COLORS } from '../models/PlayerModel';
     3→
     4→interface PlayerState {
     5→  players: Player[];
     6→  selectedPlayerId: string | null;
     7→  
     8→  // Actions
     9→  initializePlayers: () => void;
    10→  updatePlayerPosition: (playerId: string, position: [number, number, number]) => void;
    11→  updatePlayerRotation: (playerId: string, rotation: number) => void;
    12→  selectPlayer: (playerId: string | null) => void;
    13→  resetPlayers: () => void;
    14→  getPlayer: (playerId: string) => Player | undefined;
    15→  getTeamPlayers: (teamId: 'team1' | 'team2') => Player[];
    16→}
    17→
    18→export const usePlayerStore = create<PlayerState>((set, get) => ({
    19→  players: [],
    20→  selectedPlayerId: null,
    21→  
    22→  initializePlayers: () => {
    23→    const team1Players = createTeamPlayers('team1', DEFAULT_TEAM_COLORS.team1);
    24→    const team2Players = createTeamPlayers('team2', DEFAULT_TEAM_COLORS.team2);
    25→    
    26→    // Position players in initial formation (spread across field)
    27→    const positionedTeam1 = team1Players.map((player, index) => ({
    28→      ...player,
    29→      position: [
    30→        -30 + (index % 6) * 10,
    31→        0,
    32→        -40 + Math.floor(index / 6) * 20,
    33→      ] as [number, number, number],
    34→    }));
    35→    
    36→    const positionedTeam2 = team2Players.map((player, index) => ({
    37→      ...player,
    38→      position: [
    39→        30 - (index % 6) * 10,
    40→        0,
    41→        -40 + Math.floor(index / 6) * 20,
    42→      ] as [number, number, number],
    43→    }));
    44→    
    45→    set({ players: [...positionedTeam1, ...positionedTeam2] });
    46→  },
    47→  
    48→  updatePlayerPosition: (playerId, position) => {
    49→    set((state) => ({
    50→      players: state.players.map((player) =>
    51→        player.id === playerId ? { ...player, position } : player
    52→      ),
    53→    }));
    54→  },
    55→  
    56→  updatePlayerRotation: (playerId, rotation) => {
    57→    set((state) => ({
    58→      players: state.players.map((player) =>
    59→        player.id === playerId ? { ...player, rotation } : player
    60→      ),
    61→    }));
    62→  },
    63→  
    64→  selectPlayer: (playerId) => {
    65→    set({ selectedPlayerId: playerId });
    66→  },
    67→  
    68→  resetPlayers: () => {
    69→    get().initializePlayers();
    70→  },
    71→  
    72→  getPlayer: (playerId) => {
    73→    return get().players.find((p) => p.id === playerId);
    74→  },
    75→  
    76→  getTeamPlayers: (teamId) => {
    77→    return get().players.filter((p) => p.teamId === teamId);
    78→  },
    79→}));
    80→

