    56→ */
    57→function storedToFormation(stored: StoredFormation): Formation {
    58→  return {
    59→    id: `custom-${stored.id}`,
    60→    name: stored.name,
    61→    description: stored.description,
    62→    category: 'custom',
    63→    positions: stored.positions,
    64→    createdAt: new Date(stored.createdAt),
