    69→export const useFormationStore = create<FormationState>((set, get) => ({
    70→  customFormations: [],
    71→  currentFormation: null,
    72→  isLoading: false,
    73→
    74→  loadCustomFormations: async () => {
    75→    set({ isLoading: true });
    76→    try {
    77→      const storedFormations = await db.customFormations
    78→        .orderBy('createdAt')
    79→        .reverse()
    80→        .toArray();
    81→      const formations = storedFormations.map(storedToFormation);
    82→      set({ customFormations: formations, isLoading: false });
    83→    } catch (error) {
    84→      console.error('Error loading custom formations:', error);
    85→      set({ isLoading: false });
    86→    }
    87→  },
    88→
    89→  saveCustomFormation: async (name, description, positions, thumbnail) => {
    90→    try {
    91→      const storedFormation: StoredFormation = {
    92→        formationId: `custom-${Date.now()}`,
    93→        name,
    94→        description,
    95→        positions,
    96→        createdAt: new Date().toISOString(),
    97→        thumbnail,
    98→      };
    99→      const id = await db.customFormations.add(storedFormation);
   100→      // Reload formations to update the list
   101→      await get().loadCustomFormations();
   102→      return id;
   103→    } catch (error) {
   104→      console.error('Error saving custom formation:', error);
   105→      throw error;
   106→    }
   107→  },
   108→
   109→  deleteCustomFormation: async (id) => {
   110→    try {
   111→      await db.customFormations.delete(id);
   112→      // Reload formations to update the list
   113→      await get().loadCustomFormations();
   114→      // Clear current formation if it was the deleted one
   115→      const current = get().currentFormation;
   116→      if (current && current.id === `custom-${id}`) {
   117→        set({ currentFormation: null });
   118→      }
   119→    } catch (error) {
   120→      console.error('Error deleting custom formation:', error);
   121→      throw error;
   122→    }
   123→  },
   124→
   125→  setCurrentFormation: (formation) => {
   126→    set({ currentFormation: formation });
