   128→
   129→  getCustomFormation: async (id) => {
   130→    try {
   131→      const stored = await db.customFormations.get(id);
   132→      if (stored) {
   133→        return storedToFormation(stored);
   134→      }
   135→      return undefined;
   136→    } catch (error) {
   137→      console.error('Error getting custom formation:', error);
   138→      throw error;
   139→    }
