    95→                <div>
    96→                  <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-2">
    97→                    Custom Formations
    98→                  </h3>
    99→                  <div className="space-y-2">
   100→                    {customFormations.map((formation) => (
   101→                      <FormationItem
   102→                        key={formation.id}
   103→                        formation={formation}
   104→                        onApply={handleApplyFormation}
