     8→export interface PlayerPosition {
     9→  /** Player number (1-18 for team1, 1-18 for team2) */
    10→  playerNumber: number;
    11→  /** Team identifier matching the existing Player model */
    12→  teamId: 'team1' | 'team2';
    13→  /** Position coordinates [x, y, z] matching the Player model format */
    14→  position: [number, number, number];
    15→  /** Optional rotation in radians */
    16→  rotation?: number;
    17→  /** Optional AFL role/position name (e.g., "CHF", "FF", "Ruck", "CHB") */
    18→  role?: string;
    19→}
    20→
    21→/**
    22→ * Formation category distinguishing pre-built from user-created templates
    23→ */
    24→export type FormationCategory = 'pre-built' | 'custom';
    25→
    26→/**
    27→ * Represents a complete formation template with positions for all 36 players
    28→ */
    29→export interface Formation {
    30→  /** Unique identifier for the formation */
    31→  id: string;
    32→  /** Display name for the formation */
    33→  name: string;
    34→  /** Brief description of the formation and its tactical purpose */
    35→  description: string;
    36→  /** Whether this is a pre-built or custom user formation */
    37→  category: FormationCategory;
    38→  /** Array of player positions (36 total: 18 per team) */
    39→  positions: PlayerPosition[];
    40→  /** Creation timestamp (primarily for custom formations) */
    41→  createdAt?: Date;
    42→  /** Optional thumbnail image as base64 or URL */
    43→  thumbnail?: string;
    44→}
    45→
    46→/**
    47→ * Schema for creating a new custom formation (without auto-generated fields)
