     1→import { useCallback, useEffect, useState } from 'react';
     2→import { useFormationStore } from '../../store/formationStore';
     3→import { usePlayerStore, PlayerUpdate } from '../../store/playerStore';
     4→import { PRE_BUILT_FORMATIONS, validateFormation } from '../../data/formations';
     5→import { Formation } from '../../types/Formation';
     6→
     7→export function FormationSelector() {
     8→  const { customFormations, isLoading, loadCustomFormations, setCurrentFormation } = useFormationStore();
     9→  const { players, updateMultiplePlayers } = usePlayerStore();
    10→  const [isOpen, setIsOpen] = useState(false);
    11→  const [isApplying, setIsApplying] = useState(false);
    12→
    13→  // Load custom formations on mount
    14→  useEffect(() => {
    15→    loadCustomFormations();
    16→  }, [loadCustomFormations]);
    17→
    18→  /**
    19→   * Convert formation positions to player updates
    20→   * Maps PlayerPosition (playerNumber + teamId) to actual player IDs
    21→   * Optimized for performance with direct array construction
    22→   */
    23→  const convertFormationToUpdates = useCallback((formation: Formation): PlayerUpdate[] => {
    24→    // Pre-allocate array for better performance
    25→    const updates: PlayerUpdate[] = new Array(formation.positions.length);
    26→
    27→    for (let i = 0; i < formation.positions.length; i++) {
    28→      const pos = formation.positions[i];
    29→      // Construct player ID from teamId and playerNumber
    30→      // Player IDs are formatted as: `${teamId}-player-${number}`
    31→      updates[i] = {
    32→        playerId: `${pos.teamId}-player-${pos.playerNumber}`,
    33→        position: pos.position,
    34→        rotation: pos.rotation,
    35→      };
    36→    }
    37→
    38→    return updates;
    39→  }, []);
    40→
    41→  /**
    42→   * Apply a formation to the current players
    43→   * Updates all 36 player positions in a single batched operation
    44→   */
    45→  const handleApplyFormation = useCallback((formation: Formation) => {
    46→    try {
    47→      setIsApplying(true);
    48→
    49→      // Validate formation has required 36 positions
    50→      if (!validateFormation(formation)) {
    51→        throw new Error(`Invalid formation: expected 36 positions (18 per team), got ${formation.positions.length}`);
    52→      }
    53→
    54→      // Check if we have all 36 players initialized
    55→      if (players.length < 36) {
    56→        throw new Error(`Not enough players: found ${players.length}, formation requires 36 players (18 per team)`);
    57→      }
    58→
    59→      // Convert formation positions to player updates
    60→      const updates = convertFormationToUpdates(formation);
    61→
    62→      // Apply all updates in a single batched operation for performance
    63→      updateMultiplePlayers(updates);
    64→
    65→      // Update the current formation in the store
    66→      setCurrentFormation(formation);
    67→
    68→      // Close the panel after successful application
    69→      setIsOpen(false);
    70→    } catch (error) {
    71→      console.error('Error applying formation:', error);
    72→      const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
    73→      alert(`Failed to apply formation: ${errorMessage}`);
    74→    } finally {
    75→      setIsApplying(false);
    76→    }
    77→  }, [players.length, convertFormationToUpdates, updateMultiplePlayers, setCurrentFormation]);
    78→
    79→  // Combine pre-built and custom formations for display
    80→  const allFormations: Formation[] = [
    81→    ...PRE_BUILT_FORMATIONS,
    82→    ...customFormations,
    83→  ];
    84→
    85→  return (
    86→    <>
    87→      <button
    88→        onClick={() => setIsOpen(!isOpen)}
    89→        className="px-4 py-2 bg-indigo-500 text-white rounded hover:bg-indigo-600 transition"
    90→      >
    91→        {isOpen ? '✕ Close' : '📋 Formations'}
    92→      </button>
    93→
    94→      {isOpen && (
    95→        <div className="absolute top-16 left-4 z-20 w-80 bg-white/95 backdrop-blur-sm rounded-lg shadow-xl p-4 max-h-[calc(100vh-120px)] overflow-y-auto">
    96→          <h2 className="text-lg font-bold mb-3">Formation Templates</h2>
    97→
    98→          {isLoading ? (
    99→            <div className="text-center py-8 text-gray-500">Loading...</div>
   100→          ) : (
   101→            <div className="space-y-4">
   102→              {/* Pre-built Formations Section */}
   103→              <div>
   104→                <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-2">
   105→                  Pre-built Formations
   106→                </h3>
   107→                <div className="space-y-2">
   108→                  {PRE_BUILT_FORMATIONS.map((formation) => (
   109→                    <FormationItem
   110→                      key={formation.id}
   111→                      formation={formation}
   112→                      onApply={handleApplyFormation}
   113→                      isApplying={isApplying}
   114→                    />
   115→                  ))}
   116→                </div>
   117→              </div>
   118→
   119→              {/* Custom Formations Section */}
   120→              {customFormations.length > 0 && (
   121→                <div>
   122→                  <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-2">
   123→                    Custom Formations
   124→                  </h3>
   125→                  <div className="space-y-2">
   126→                    {customFormations.map((formation) => (
   127→                      <FormationItem
   128→                        key={formation.id}
   129→                        formation={formation}
   130→                        onApply={handleApplyFormation}
   131→                        showDelete
   132→                        isApplying={isApplying}
   133→                      />
   134→                    ))}
   135→                  </div>
   136→                </div>
   137→              )}
   138→
   139→              {/* Empty state for custom formations */}
   140→              {customFormations.length === 0 && (
   141→                <div className="text-center py-4 text-gray-400 text-sm">
   142→                  No custom formations saved yet.
   143→                </div>
   144→              )}
   145→            </div>
   146→          )}
   147→        </div>
   148→      )}
   149→    </>
   150→  );
   151→}
   152→
   153→interface FormationItemProps {
   154→  formation: Formation;
   155→  onApply: (formation: Formation) => void;
   156→  showDelete?: boolean;
   157→  isApplying?: boolean;
   158→}
   159→
   160→function FormationItem({ formation, onApply, showDelete = false, isApplying = false }: FormationItemProps) {
   161→  const { deleteCustomFormation } = useFormationStore();
   162→
   163→  const handleDelete = async (e: React.MouseEvent) => {
   164→    e.stopPropagation();
   165→    if (confirm(`Are you sure you want to delete "${formation.name}"?`)) {
   166→      // Extract numeric ID from custom-{id} format
   167→      const idMatch = formation.id.match(/^custom-(\d+)$/);
   168→      if (idMatch) {
   169→        const numericId = parseInt(idMatch[1], 10);
   170→        try {
   171→          await deleteCustomFormation(numericId);
   172→        } catch (error) {
   173→          console.error('Error deleting formation:', error);
   174→          alert('Failed to delete formation. Please try again.');
   175→        }
   176→      }
   177→    }
   178→  };
   179→
   180→  const handleApply = useCallback(() => {
   181→    if (!isApplying) {
   182→      onApply(formation);
   183→    }
   184→  }, [isApplying, onApply, formation]);
   185→
   186→  return (
   187→    <div className="border rounded-lg p-3 hover:bg-gray-50 transition cursor-pointer group">
   188→      <div className="flex justify-between items-start">
   189→        <div className="flex-1 min-w-0" onClick={handleApply}>
   190→          <h4 className="font-semibold text-gray-900 truncate">{formation.name}</h4>
   191→          <p className="text-sm text-gray-600 mt-1 line-clamp-2">{formation.description}</p>
   192→          {formation.createdAt && (
   193→            <p className="text-xs text-gray-400 mt-1">
   194→              {new Date(formation.createdAt).toLocaleDateString()}
   195→            </p>
   196→          )}
   197→        </div>
   198→        <div className="flex gap-2 ml-2 flex-shrink-0">
   199→          <button
   200→            onClick={handleApply}
   201→            disabled={isApplying}
   202→            className={`px-3 py-1.5 text-white text-sm rounded transition ${
   203→              isApplying
   204→                ? 'bg-indigo-300 cursor-not-allowed'
   205→                : 'bg-indigo-500 hover:bg-indigo-600'
   206→            }`}
   207→          >
   208→            {isApplying ? 'Applying...' : 'Apply'}
   209→          </button>
   210→          {showDelete && (
   211→            <button
   212→              onClick={handleDelete}
   213→              disabled={isApplying}
   214→              className="px-2 py-1.5 bg-red-500 text-white text-sm rounded hover:bg-red-600 transition opacity-0 group-hover:opacity-100 disabled:opacity-50"
   215→              title="Delete formation"
   216→            >
   217→              ✕
   218→            </button>
   219→          )}
   220→</div>
   221→      </div>
   222→    </div>
   223→  );
   224→}
