     9→
    10→interface PlayerState {
    11→  players: Player[];
    12→  selectedPlayerId: string | null;
    13→
    14→  // Actions
    15→  initializePlayers: () => void;
    16→  updatePlayerPosition: (playerId: string, position: [number, number, number]) => void;
    17→  updatePlayerRotation: (playerId: string, rotation: number) => void;
    18→  updateMultiplePlayers: (updates: PlayerUpdate[]) => void;
    19→  selectPlayer: (playerId: string | null) => void;
    20→  resetPlayers: () => void;
    21→  getPlayer: (playerId: string) => Player | undefined;
    22→  getTeamPlayers: (teamId: 'team1' | 'team2') => Player[];
    23→}
    24→
    25→export const usePlayerStore = create<PlayerState>((set, get) => ({
    26→  players: [],
    27→  selectedPlayerId: null,
    28→  
    29→  initializePlayers: () => {
    30→    const team1Players = createTeamPlayers('team1', DEFAULT_TEAM_COLORS.team1);
    31→    const team2Players = createTeamPlayers('team2', DEFAULT_TEAM_COLORS.team2);
    32→    
    33→    // Position players in initial formation (spread across field)
    34→    const positionedTeam1 = team1Players.map((player, index) => ({
    35→      ...player,
    36→      position: [
    37→        -30 + (index % 6) * 10,
    38→        0,
    39→        -40 + Math.floor(index / 6) * 20,
    40→      ] as [number, number, number],
    41→    }));
    42→    
    43→    const positionedTeam2 = team2Players.map((player, index) => ({
    44→      ...player,
    45→      position: [
    46→        30 - (index % 6) * 10,
    47→        0,
    48→        -40 + Math.floor(index / 6) * 20,
    49→      ] as [number, number, number],
    50→    }));
    51→    
    52→    set({ players: [...positionedTeam1, ...positionedTeam2] });
    53→  },
    54→  
    55→  updatePlayerPosition: (playerId, position) => {
    56→    set((state) => ({
    57→      players: state.players.map((player) =>
    58→        player.id === playerId ? { ...player, position } : player
    59→      ),
    60→    }));
    61→  },
    62→  
    63→  updatePlayerRotation: (playerId, rotation) => {
    64→    set((state) => ({
    65→      players: state.players.map((player) =>
    66→        player.id === playerId ? { ...player, rotation } : player
    67→      ),
    68→    }));
    69→  },
    70→
    71→  updateMultiplePlayers: (updates) => {
    72→    set((state) => {
    73→      // Create a map for O(1) lookup of updates by playerId
    74→      const updateMap = new Map(
    75→        updates.map((update) => [update.playerId, update])
    76→      );
    77→
    78→      return {
    79→        players: state.players.map((player) => {
    80→          const update = updateMap.get(player.id);
    81→          if (update) {
    82→            return {
    83→              ...player,
    84→              position: update.position,
    85→              ...(update.rotation !== undefined && { rotation: update.rotation }),
    86→            };
    87→          }
    88→          return player;
    89→        }),
    90→      };
    91→    });
    92→  },
    93→
    94→  selectPlayer: (playerId) => {
    95→    set({ selectedPlayerId: playerId });
    96→  },
    97→  
    98→  resetPlayers: () => {
