    45→      ...player,
    46→      position: [
    47→        -30 + (index % 6) * 10,
    48→        0,
    49→        -40 + Math.floor(index / 6) * 20,
    50→      ] as [number, number, number],
    51→    }));
    52→    
    53→    const positionedTeam2 = team2Players.map((player, index) => ({
    54→      ...player,
    55→      position: [
    56→        30 - (index % 6) * 10,
    57→        0,
    58→        -40 + Math.floor(index / 6) * 20,
    59→      ] as [number, number, number],
    60→    }));
    61→    
    62→    set({ players: [...positionedTeam1, ...positionedTeam2] });
    63→  },
    64→  
    65→  updatePlayerPosition: (playerId, position) => {
    66→    set((state) => ({
    67→      players: state.players.map((player) =>
    68→        player.id === playerId ? { ...player, position } : player
    69→      ),
    70→    }));
    71→  },
    72→  
    73→  updatePlayerRotation: (playerId, rotation) => {
    74→    set((state) => ({
    75→      players: state.players.map((player) =>
    76→        player.id === playerId ? { ...player, rotation } : player
    77→      ),
    78→    }));
    79→  },
    80→
    81→  updateMultiplePlayers: (updates) => {
    82→    // Set updating flag before starting
    83→    set({ isUpdating: true });
    84→
    85→    try {
    86→      set((state) => {
    87→        // Create a map for O(1) lookup of updates by playerId
    88→        const updateMap = new Map(
    89→          updates.map((update) => [update.playerId, update])
    90→        );
    91→
    92→        return {
    93→          players: state.players.map((player) => {
    94→            const update = updateMap.get(player.id);
    95→            if (update) {
    96→              return {
    97→                ...player,
    98→                position: update.position,
    99→                ...(update.rotation !== undefined && { rotation: update.rotation }),
   100→              };
   101→            }
   102→            return player;
   103→          }),
   104→          isUpdating: false,
   105→        };
   106→      });
   107→    } catch {
   108→      // Ensure flag is cleared even on error
   109→      set({ isUpdating: false });
   110→    }
   111→  },
   112→
   113→  selectPlayer: (playerId) => {
   114→    set({ selectedPlayerId: playerId });
   115→  },
   116→  
   117→  resetPlayers: () => {
   118→    get().initializePlayers();
   119→  },
   120→  
   121→  getPlayer: (playerId) => {
   122→    return get().players.find((p) => p.id === playerId);
   123→  },
   124→  
   125→  getTeamPlayers: (teamId) => {
   126→    return get().players.filter((p) => p.teamId === teamId);
   127→  },
   128→
   129→  setDragging: (isDragging) => {
   130→    set({ isDragging });
   131→  },
   132→
   133→  canApplyFormation: () => {
   134→    const state = get();
   135→    // Prevent formation application if currently updating or dragging
   136→    return !state.isUpdating && !state.isDragging;
   137→  },
   138→}));
